import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"十五删","description":"","frontmatter":{"title":"十五删","date":"2026-11-17T00:00:00.000Z","seq":15,"categories":["美文","声律启蒙"],"collection":"《声律启蒙 · 上卷》","tags":["声律启蒙","清"],"poem":true,"poem_quote":false,"author":"佚名","source_book":"声律启蒙"},"headers":[],"relativePath":"blogs/声律启蒙·上卷/十五删.md","filePath":"blogs/声律启蒙·上卷/十五删.md"}'),r={name:"blogs/声律启蒙·上卷/十五删.md"};function p(_,e,l,c,n,i){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="十五删" tabindex="-1">十五删 <a class="header-anchor" href="#十五删" aria-label="Permalink to &quot;十五删&quot;">​</a></h1><p class="poem-meta">清 · 佚名　·　上卷</p><div class="poem"><p class="poem-stanza">兴对废，附对攀，露草对霜菅，歌廉对借寇，习孔对希颜。山垒垒，水潺潺，奉壁对探镮。礼由公旦作，诗本仲尼删。驴困客方经灞水，鸡鸣人已出函关。几夜霜飞，已有苍鸿辞北塞；数朝雾暗，岂无玄豹隐南山。</p><p class="poem-stanza">犹对尚，侈对悭，雾髻对烟鬟。莺啼对鹊噪，独鹤对双鹇。黄牛峡，金马山，结草对衔环。昆山惟玉集，合浦有珠还。阮籍旧能为眼白，老莱新爱着衣斑。栖迟避世人，草衣木食；窈窕倾城女，云鬓花颜。</p><p class="poem-stanza">姚对宋，柳对颜，赏善对惩奸。愁中对梦里，巧慧对痴顽。孔北海，谢东山，使越对征蛮，淫声闻濮上，离曲听阳关。骁将袍披仁贵白，小儿衣着老莱斑。茅舍无人，难却尘埃生榻上；竹亭有客，尚留风月在窗间。</p></div>',3)])])}const u=a(r,[["render",p]]);export{d as __pageData,u as default};
